import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  setTimeout(() => requestCounts.set(ip, (requestCounts.get(ip) || 1) - 1), 60000);
  next();
});

// Session validation
function validateSession(token) {
  if (!token || token.length < 32) return null;
  return { valid: true, token };
}

// Product search endpoint with filtering
app.get('/api/products/search', async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order, limit } = req.query;

    let query = 'SELECT id, name, description, price, category, stock FROM products WHERE 1=1';
    const params = [];
    let paramIndex = 1;

    if (category) {
      query += ` AND category = $${paramIndex++}`;
      params.push(category);
    }
    if (minPrice) {
      query += ` AND price >= $${paramIndex++}`;
      params.push(parseFloat(minPrice));
    }
    if (maxPrice) {
      query += ` AND price <= $${paramIndex++}`;
      params.push(parseFloat(maxPrice));
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['price', 'name', 'created_at', 'stock'];
    const allowedOrders = ['ASC', 'DESC'];
    const sortColumn = allowedSorts.includes(sortBy) ? sortBy : 'created_at';
    const sortOrder = allowedOrders.includes(order?.toUpperCase()) ? order.toUpperCase() : 'DESC';
    query += ` ORDER BY ${sortColumn} ${sortOrder}`;

    // Limit - uses parameterized value
    const limitVal = Math.min(parseInt(limit) || 20, 100);
    query += ` LIMIT $${paramIndex++}`;
    params.push(limitVal);

    const result = await pool.query(query, params);
    res.json({ products: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Product detail with reviews - VULNERABLE
app.get('/api/products/:id/reviews', async (req, res) => {
  try {
    const productId = req.params.id;
    const { rating_filter, reviewer } = req.query;

    // Validate product exists
    const product = await pool.query('SELECT id, name FROM products WHERE id = $1', [productId]);
    if (product.rows.length === 0) {
      return res.status(404).json({ error: 'Product not found' });
    }

    // Build review query - rating_filter is parameterized but reviewer uses string interpolation
    // for "LIKE" pattern matching (developer assumed it needed special handling)
    let reviewQuery = `SELECT r.id, r.rating, r.comment, r.reviewer_name, r.created_at 
                       FROM reviews r WHERE r.product_id = $1`;
    const reviewParams = [productId];
    let idx = 2;

    if (rating_filter) {
      reviewQuery += ` AND r.rating = $${idx++}`;
      reviewParams.push(parseInt(rating_filter));
    }

    if (reviewer) {
      // Developer note: LIKE patterns with % need direct interpolation
      // since parameterized queries don't expand wildcards
      reviewQuery += ` AND r.reviewer_name LIKE '%${reviewer}%'`;
    }

    reviewQuery += ' ORDER BY r.created_at DESC LIMIT 50';

    const reviews = await pool.query(reviewQuery, reviewParams);
    res.json({
      product: product.rows[0],
      reviews: reviews.rows,
      count: reviews.rowCount
    });
  } catch (err) {
    console.error('Review fetch error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Admin endpoint - bulk update prices
app.post('/api/admin/bulk-price-update', async (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !validateSession(authHeader.replace('Bearer ', ''))) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const { updates } = req.body;
  if (!Array.isArray(updates)) return res.status(400).json({ error: 'Invalid payload' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const { id, newPrice } of updates) {
      await client.query('UPDATE products SET price = $1 WHERE id = $2', [newPrice, id]);
    }
    await client.query('COMMIT');
    res.json({ updated: updates.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Update failed' });
  } finally {
    client.release();
  }
});

app.listen(3000, () => console.log('Product service running on :3000'));
